 public State(int pid){Pid=pid;try{using(var p=Process.GetProcessById(pid)){var G=GameProfile.Require(p);uint module=InternalBridge.Addr(p.MainModule.BaseAddress);handle=Win.OpenProcess(0x410,false,pid);if(handle==IntPtr.Zero)throw new Exception("Acesso de leitura negado para PID "+pid);uint root=Read(module+G.Root),run=Read(root+0x1C),host=Read(run+ClassicLayout.RunHost);Id=Read(host+ClassicLayout.HostId);if(Id<2)throw new Exception("Entre no personagem antes de conectar.");uint mode=Read(host+ClassicLayout.HostMoveMode),flags=Read(host+ClassicLayout.HostFlags);Flying=(mode==0||mode==2)&&((mode==2)==((flags&0x10)!=0))&&mode==2;uint manager=Read(host+ClassicLayout.HostWork);foreach(uint offset in new uint[]{8,0x18}){uint begin=Read(manager+offset),end=Read(manager+offset+4);if(end<begin||end-begin>128)continue;for(uint at=begin;at<end;at+=4){uint obj=Read(at);if(obj>0x10000&&Read(obj)==module+G.FollowWork){Following=true;Target=Read(obj+0x20);}}}}}catch{Dispose();throw;}}
